diff --git a/tests/sites.test.js b/tests/sites.test.js
new file mode 100644
index 0000000..becd05d
--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,91 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, fresh, seed } from "./helpers.js";
+import { migrate } from "../src/db/migrations.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+function twoSites() {
+  const store = fresh();
+  store.data.batches.push({ ...store.data.batches[0], id: 10, qty: 20, location: "annex-fridge", expires: "2026-10-29" });
+  store.data.seq.batch = 10;
+  return app(store);
+}
+
+test("schema 2 migration preserves records and assigns existing locations to main", () => {
+  const old = seed();
+  old.schemaVersion = 2;
+  delete old.sites;
+  old.locations = old.locations.slice(0, 3).map(({ site, ...location }) => location);
+  const snapshot = structuredClone(old);
+  const upgraded = migrate(old);
+  assert.equal(upgraded.schemaVersion, 3);
+  assert.deepEqual(upgraded.sites, [{ id: "main", name: "Main kitchen" }]);
+  assert.ok(upgraded.locations.every((l) => l.site === "main"));
+  assert.deepEqual(upgraded.batches, old.batches);
+  assert.deepEqual(old, snapshot);
+});
+
+test("site header scopes batches, on hand, alerts and stock value; catalogs stay shared", async () => {
+  const { handle } = twoSites();
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+  const item = (await handle({ path: "/items/1", headers: annex })).body;
+  assert.equal(item.onHand, 20);
+  assert.deepEqual(item.batches.map((b) => b.id), [10]);
+  assert.equal((await handle({ path: "/items", headers: annex })).body.length, 6);
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body.map((b) => b.id), [10]);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ path: "/batches/10" })).status, 404);
+  const alerts = (await handle({ path: "/alerts", headers: annex })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.id), [10]);
+  assert.equal(alerts.lowStock.find((i) => i.itemId === 2).qty, 0);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 3600);
+  for (const path of ["/suppliers", "/dishes", "/recipes/1/cost"]) {
+    assert.deepEqual((await handle({ path, headers: annex })).body, (await handle({ path })).body);
+  }
+  const unknown = await handle({ path: "/items", headers: { "x-larder-site": "missing" } });
+  assert.equal(unknown.status, 400);
+  assert.equal(unknown.body.error.code, "unknown_site");
+});
+
+test("cooking and waste cannot consume the other site's stock", async () => {
+  const { handle, store } = twoSites();
+  const before = structuredClone(store.data);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } })).status, 409);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: annex, body: { qty: 1 } })).status, 404);
+  assert.deepEqual(store.data, before);
+  store.data.recipes.push({ id: 3, portions: 1, ingredients: [{ itemId: 1, qty: 2 }] });
+  assert.equal((await handle({ method: "POST", path: "/recipes/3/cook", headers: annex, body: { portions: 1 } })).status, 200);
+  assert.equal(store.data.batches.find((b) => b.id === 10).qty, 18);
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+});
+
+test("stock-takes enforce site on locations, counts and finishing", async () => {
+  const { handle, store } = twoSites();
+  const post = (path, body, headers = annex) => handle({ method: "POST", path, body, headers });
+  assert.equal((await post("/stocktakes", { location: "dry" })).status, 400);
+  const take = (await post("/stocktakes", { location: "annex-fridge" })).body;
+  assert.equal((await post(`/stocktakes/${take.id}/counts`, { batchId: 1, counted: 1 })).status, 404);
+  assert.equal((await post(`/stocktakes/${take.id}/counts`, { batchId: 10, counted: 15 }, {})).status, 404);
+  assert.equal((await post(`/stocktakes/${take.id}/counts`, { batchId: 10, counted: 15 })).status, 200);
+  assert.equal((await post(`/stocktakes/${take.id}/finish`, {}, {})).status, 404);
+  assert.equal((await post(`/stocktakes/${take.id}/finish`, {})).status, 200);
+  assert.equal(store.data.batches.find((b) => b.id === 10).qty, 15);
+  assert.equal(store.data.movements.at(-1).batchId, 10);
+});
+
+test("receiving validates every location before creating site-local batches", async () => {
+  const { handle, store } = twoSites();
+  const before = structuredClone(store.data);
+  const lots = [
+    { lot: "milk", expires: null, location: "annex-fridge" },
+    { lot: "butter", expires: null, location: "fridge" },
+  ];
+  const receive = () => handle({ method: "POST", path: "/orders/2/receive", headers: annex, body: { lots } });
+  assert.equal((await receive()).status, 400);
+  assert.deepEqual(store.data, before);
+  lots[1].location = "annex-fridge";
+  assert.equal((await receive()).status, 200);
+  assert.equal((await handle({ path: "/items/2", headers: annex })).body.onHand, 12);
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
+});
